using a19char::Q;using a19char::require;using a19char::rational;
using Clock=std::chrono::steady_clock;
constexpr uint32_t populations[]={0,4,36,386,4279,39908,293306,1651060,6958562};
constexpr uint64_t roster_rows=27230728;
inline uint64_t little(const unsigned char*p,int bytes){uint64_t x=0;for(int j=bytes-1;j>=0;--j)x=(x<<8)|p[j];return x;}
inline uint32_t big(const unsigned char*p,int bytes){uint32_t x=0;for(int j=0;j<bytes;++j)x=(x<<8)|p[j];return x;}
inline void put(std::ostream&out,uint64_t value,int bytes){for(int j=0;j<bytes;++j)out.put(char((value>>(8*j))&255));require(bool(out),"complete binary write");}
struct Mapped {
 int fd=-1;size_t size=0;const unsigned char*p=nullptr;
 explicit Mapped(const std::string&path){fd=open(path.c_str(),O_RDONLY);require(fd>=0,"open frozen input");struct stat s{};require(fstat(fd,&s)==0&&s.st_size>0,"frozen input size");size=s.st_size;void*x=mmap(nullptr,size,PROT_READ,MAP_PRIVATE,fd,0);require(x!=MAP_FAILED,"read-only input mapping");p=static_cast<const unsigned char*>(x);}
 ~Mapped(){if(p)munmap(const_cast<unsigned char*>(p),size);if(fd>=0)close(fd);}
 Mapped(const Mapped&)=delete;Mapped&operator=(const Mapped&)=delete;
};
inline std::ofstream fresh(const std::string&path){int fd=open(path.c_str(),O_WRONLY|O_CREAT|O_EXCL,0600);require(fd>=0,"fresh immutable output");require(close(fd)==0,"fresh output close");std::ofstream out(path,std::ios::binary);require(bool(out),"open owned fresh output");return out;}
inline void header(std::ostream&out,const char*magic,int k,uint32_t count,bool dense){out.write(magic,8);put(out,k,4);put(out,count,4);put(out,populations[k],4);put(out,dense?1:0,4);put(out,0,8);}
inline void check_header(const Mapped&in,const char*magic,int k,uint32_t count,bool dense){require(in.size>=32&&std::string(reinterpret_cast<const char*>(in.p),8)==std::string(magic,8),"exact packed cache magic");require(little(in.p+8,4)==uint64_t(k)&&little(in.p+12,4)==count&&little(in.p+16,4)==populations[k]&&little(in.p+20,4)==unsigned(dense)&&little(in.p+24,8)==0,"exact packed cache header");}
struct Record {
 int k=0,index=0;uint32_t id=0,det=0;int8_t g[8][8]{};uint8_t basis[8][8]{};int32_t u[8]{};Q value;
};
inline size_t geometry_stride(int k){int t=k*(k+1)/2;return 5+(t+1)/2+4*k+t;}
inline long determinant(const Record&r){long a[8][8]{};for(int i=0;i<r.k;++i)for(int j=0;j<r.k;++j)a[i][j]=r.g[i][j];long previous=1;for(int p=0;p<r.k-1;++p){long pivot=a[p][p];require(pivot>0,"positive leading Gram minor");for(int i=p+1;i<r.k;++i)for(int j=p+1;j<r.k;++j){long n=a19char::checked_long((__int128)pivot*a[i][j]-(__int128)a[i][p]*a[p][j]);require(n%previous==0,"exact determinant division");a[i][j]=n/previous;}for(int i=p+1;i<r.k;++i)a[i][p]=0;previous=pivot;}return a[r.k-1][r.k-1];}
inline void check_geometry(const Record&r,bool check_u){require(r.k>=1&&r.k<=8&&r.id<populations[r.k],"proper type identity");long idx=1;for(int i=0;i<r.k;++i){require(r.basis[i][i]>0,"positive image basis diagonal");idx*=r.basis[i][i];for(int j=0;j<i;++j)require(r.basis[i][j]<r.basis[i][i],"canonical image basis residue");for(int j=0;j<r.k;++j)require(std::abs(r.g[i][j])<=4&&r.g[i][j]==r.g[j][i]&&(i!=j||r.g[i][i]>0),"original packed Gram bounds");}require(idx==r.index&&idx>0&&idx<=16,"full proper image lattice index");require(r.det>0&&r.det<=65536&&determinant(r)==r.det,"independent exact Gram determinant");
 if(check_u)for(int i=0;i<r.k;++i){long v=0;require(std::abs(int64_t(r.u[i]))<=131072,"stored solve-vector bound");for(int j=0;j<r.k;++j)v+=r.g[i][j]*int64_t(r.u[j]);require(v==r.det,"complete G u equals determinant ones");}}
inline void prepare_u(Record&r){long a[8][9]{};for(int i=0;i<r.k;++i){for(int j=0;j<r.k;++j)a[i][j]=r.g[i][j];a[i][r.k]=1;}long previous=1;for(int p=0;p<r.k;++p){long pivot=a[p][p];require(pivot>0,"positive fraction-free solve pivot");for(int i=0;i<r.k;++i)if(i!=p){long x=a[i][p];for(int j=0;j<=r.k;++j)if(j!=p){long numerator=a19char::checked_long((__int128)pivot*a[i][j]-(__int128)x*a[p][j]);require(numerator%previous==0,"exact solve division");a[i][j]=numerator/previous;}a[i][p]=0;}previous=pivot;}require(previous>0&&previous<=65536,"exact Gram determinant width");r.det=previous;for(int i=0;i<r.k;++i){require(std::abs(a[i][r.k])<=131072,"exact solve-vector width");r.u[i]=a[i][r.k];}check_geometry(r,true);}
inline std::array<long,8> checker_solve(const Record&r){long a[8][16]{};for(int i=0;i<r.k;++i){for(int j=0;j<r.k;++j)a[i][j]=r.g[i][j];a[i][r.k+i]=1;}long previous=1;
 for(int p=0;p<r.k;++p){long pivot=a[p][p];require(pivot>0,"checker positive Gram pivot");for(int i=0;i<r.k;++i)if(i!=p){long x=a[i][p];for(int j=0;j<2*r.k;++j)if(j!=p){long numerator=a19char::checked_long((__int128)pivot*a[i][j]-(__int128)x*a[p][j]);require(numerator%previous==0,"checker exact adjugate division");a[i][j]=numerator/previous;}a[i][p]=0;}previous=pivot;}require(previous==r.det,"checker determinant agrees with stored geometry");std::array<long,8>result{};
 for(int i=0;i<r.k;++i)for(int j=0;j<r.k;++j){long value=0;for(int h=0;h<r.k;++h)value+=r.g[i][h]*a[h][r.k+j];require(value==(i==j?previous:0),"checker complete adjugate identity");result[i]+=a[i][r.k+j];}return result;}
inline Record source_record(const Mapped&types,int k,uint32_t id){require(id<populations[k]&&types.size==size_t(populations[k])*(k==8?126:73),"complete accepted type source layout");Record r;r.k=k;r.id=id;auto p=types.p+size_t(id)*(k==8?126:73);r.index=k==8?big(p,2):p[0];int off=k==8?2:1;for(int i=0;i<k;++i)for(int j=0;j<=i;++j)r.g[i][j]=r.g[j][i]=int(p[off++])-4;for(int i=0;i<k;++i)for(int j=0;j<=i;++j){unsigned entry=k==8?big(p+off,2):p[off];off+=k==8?2:1;require(entry<=255,"accepted image basis byte bound");r.basis[i][j]=entry;}return r;}
inline void save_geometry(std::ostream&out,const Record&r){put(out,r.det,4);put(out,r.index,1);std::vector<int>g;for(int i=0;i<r.k;++i)for(int j=0;j<=i;++j)g.push_back(r.g[i][j]+4);for(size_t i=0;i<g.size();i+=2)put(out,g[i]|(i+1<g.size()?g[i+1]<<4:0),1);for(int i=0;i<r.k;++i)put(out,uint32_t(r.u[i]),4);for(int i=0;i<r.k;++i)for(int j=0;j<=i;++j)put(out,r.basis[i][j],1);}
inline Record decode_geometry(const unsigned char*p,int k,uint32_t id){Record r;r.k=k;r.id=id;r.det=little(p,4);r.index=p[4];p+=5;int t=k*(k+1)/2;std::vector<int>g;for(int at=0;at<t;at+=2){int byte=*p++;g.push_back((byte&15)-4);if(at+1<t)g.push_back((byte>>4)-4);else require(byte>>4==0,"packed Gram padding");}int at=0;for(int i=0;i<k;++i)for(int j=0;j<=i;++j)r.g[i][j]=r.g[j][i]=g[at++];for(int i=0;i<k;++i){r.u[i]=int32_t(uint32_t(little(p,4)));p+=4;}for(int i=0;i<k;++i)for(int j=0;j<=i;++j)r.basis[i][j]=*p++;return r;}
inline void save_rational(std::ostream&out,const Q&q){mpz_class n=q.get_num(),d=q.get_den(),m=abs(n);size_t nl=n==0?0:(mpz_sizeinbase(n.get_mpz_t(),2)+63)/64,dl=(mpz_sizeinbase(d.get_mpz_t(),2)+63)/64;require(nl<=65535&&dl>0&&dl<=65535,"exact scalar limb counts");put(out,n==0?0:n>0?1:2,1);put(out,nl,2);put(out,dl,2);std::vector<unsigned char>bytes(8*std::max(nl,dl));size_t written;if(nl){mpz_export(bytes.data(),&written,-1,8,-1,0,m.get_mpz_t());require(written==nl,"exact numerator export");out.write(reinterpret_cast<char*>(bytes.data()),8*nl);}mpz_export(bytes.data(),&written,-1,8,-1,0,d.get_mpz_t());require(written==dl,"exact denominator export");out.write(reinterpret_cast<char*>(bytes.data()),8*dl);require(bool(out),"complete rational write");}
inline Q decode_rational(const unsigned char*begin,const unsigned char*end){require(end-begin>=5,"complete rational header");int sign=begin[0];size_t nl=little(begin+1,2),dl=little(begin+3,2);require(sign<=2&&dl>0&&(sign==0)==(nl==0)&&size_t(end-begin)==5+8*(nl+dl),"exact rational payload shape");mpz_class n,d;mpz_import(n.get_mpz_t(),nl,-1,8,-1,0,begin+5);mpz_import(d.get_mpz_t(),dl,-1,8,-1,0,begin+5+8*nl);require(d>0&&(nl==0||(n>0&&(mpz_sizeinbase(n.get_mpz_t(),2)+63)/64==nl))&&(mpz_sizeinbase(d.get_mpz_t(),2)+63)/64==dl,"canonical rational limb lengths");if(sign==2)n=-n;Q value(n,d);value.canonicalize();require(value.get_num()==n&&value.get_den()==d,"reduced canonical packed rational");return value;}
struct CacheLevel {
 int k;uint32_t count;bool dense;Mapped ids,geometry,offsets,values;
 CacheLevel(const std::string&dir,int level,bool checker):k(level),ids(dir+"/q"+std::to_string(k)+".ids"),geometry(dir+"/q"+std::to_string(k)+".geometry"),offsets(dir+"/q"+std::to_string(k)+(checker?".alpha-offsets":".weight-offsets")),values(dir+"/q"+std::to_string(k)+(checker?".alphas":".weights")){
  require(ids.size>=32,"complete cache ID header");count=little(ids.p+12,4);dense=little(ids.p+20,4);require(count>0&&count<=populations[k],"declared cache population");check_header(ids,"A19IDS01",k,count,dense);require(ids.size==32+(dense?0:4ull*count)&&(!dense||count==populations[k]),"complete dense or selected cache IDs");check_header(geometry,"A19GEO01",k,count,dense);check_header(offsets,checker?"A19AOF01":"A19WOF01",k,count,dense);check_header(values,checker?"A19ALP01":"A19WGT01",k,count,dense);require(geometry.size==32+count*geometry_stride(k)&&offsets.size==32+8ull*(count+1),"complete packed geometry and offsets");require(little(offsets.p+32,8)==32&&little(offsets.p+32+8ull*count,8)==values.size,"complete variable scalar offsets");if(!dense)for(uint32_t at=0;at<count;++at)require(id_at(at)<populations[k]&&(!at||id_at(at-1)<id_at(at)),"strict selected canonical type IDs");}
 uint32_t id_at(uint32_t at)const{return dense?at:little(ids.p+32+4ull*at,4);}
 uint32_t locate(uint32_t id)const{require(id<populations[k],"requested canonical type range");if(dense)return id;uint32_t lo=0,hi=count;while(lo<hi){uint32_t mid=(lo+hi)/2;if(id_at(mid)<id)lo=mid+1;else hi=mid;}require(lo<count&&id_at(lo)==id,"complete requested lower type in selected cache");return lo;}
 Record get(uint32_t id)const{uint32_t at=locate(id);Record r=decode_geometry(geometry.p+32+geometry_stride(k)*at,k,id);uint64_t begin=little(offsets.p+32+8ull*at,8),end=little(offsets.p+40+8ull*at,8);require(begin>=32&&begin<end&&end<=values.size,"exact per-type scalar offset span");r.value=decode_rational(values.p+begin,values.p+end);return r;}
};
struct Atlas {
 int normals[42][10]{},actions[6][42]{},coordinates[6][10]{},h[42][42]{};uint64_t combinations[43][10]{};
 explicit Atlas(const std::string&geometry){std::ifstream in(geometry+"/atlas.txt");for(auto&r:normals)for(int&v:r)require(bool(in>>v)&&std::abs(v)<=1,"literal original atlas normal");for(auto&r:actions)for(int&v:r)require(bool(in>>v)&&v>=0&&v<42,"literal normal action");for(auto&r:coordinates)for(int&v:r)require(bool(in>>v)&&v>=0&&v<10,"literal coordinate action");std::string tail;require(!(in>>tail),"exact atlas tail");for(int g=0;g<6;++g){std::set<int>rows(actions[g],actions[g]+42),cols(coordinates[g],coordinates[g]+10);require(rows.size()==42&&cols.size()==10,"bijective atlas actions");for(int i=0;i<42;++i)for(int c=0;c<10;++c)require(normals[actions[g][i]][coordinates[g][c]]==normals[i][c],"actual original group transport");}for(int i=0;i<42;++i){for(int j=0;j<42;++j)for(int c=0;c<10;++c)h[i][j]+=normals[i][c]*normals[j][c];require(h[i][i]>0&&h[i][i]<=4,"original primitive norm bound");}for(int n=0;n<=42;++n){combinations[n][0]=1;for(int k=1;k<=9;++k)combinations[n][k]=n?combinations[n-1][k-1]+combinations[n-1][k]:0;}}
 uint32_t rank(const std::vector<int>&ids)const{uint64_t ordinal=0;int previous=-1,k=ids.size();for(int j=0;j<k;++j){require(ids[j]>previous&&ids[j]<42,"ordered original support");for(int c=previous+1;c<ids[j];++c)ordinal+=combinations[41-c][k-1-j];previous=ids[j];}require(ordinal<UINT32_MAX,"original ordinal width");return ordinal;}
 std::array<int,9>unrank(uint32_t ordinal)const{require(ordinal<combinations[42][9],"original nine ordinal range");std::array<int,9>ids{};uint64_t left=ordinal;int previous=-1;for(int j=0;j<9;++j){int candidate=previous+1;while(candidate<42){uint64_t block=combinations[41-candidate][8-j];if(left<block)break;left-=block;++candidate;}require(candidate<42,"complete original unrank");ids[j]=candidate;previous=candidate;}require(left==0&&rank(std::vector<int>(ids.begin(),ids.end()))==ordinal,"exact original ordinal roundtrip");return ids;}
 a19char::Normals literal(const std::array<int,9>&ids)const{a19char::Normals n{};for(int i=0;i<9;++i)for(int c=0;c<10;++c)n[i][c]=normals[ids[i]][c];return n;}
 long subset_index(const std::vector<int>&ids)const{int k=ids.size();long a[8][10]{};for(int i=0;i<k;++i)for(int c=0;c<10;++c)a[i][c]=normals[ids[i]][c];long index=1;for(int i=0;i<k;++i){int p=i;while(p<10&&!a[i][p])++p;require(p<10,"independent proper subset");for(int r=0;r<k;++r)std::swap(a[r][i],a[r][p]);for(int c=i+1;c<10;++c)while(a[i][c]){long q=a[i][i]/a[i][c];for(int r=0;r<k;++r){long v=a19char::checked_long((__int128)a[r][i]-(__int128)q*a[r][c]);a[r][i]=a[r][c];a[r][c]=v;}}index*=std::abs(a[i][i]);}return index;}
};
struct Lower {Record record;std::array<int,8>positions{};};
struct ScalarEngine {
 Atlas atlas;bool checker;std::unique_ptr<Mapped>lookups[8];Mapped join;std::unique_ptr<CacheLevel>levels[9];std::unordered_map<uint64_t,Record>low_cache;uint64_t hits=0,misses=0,lookups_done=0;double lookup_seconds=0,decode_seconds=0,transport_seconds=0,base_seconds=0,correction_seconds=0;a19char::CorrectionStats correction_stats;
 ScalarEngine(const std::string&cache,const std::string&geometry,const std::string&q8index,bool check):atlas(geometry),checker(check),join(q8index){require(join.size==10480218ull*12,"complete original q8 index");for(int k=1;k<=8;++k){levels[k]=std::make_unique<CacheLevel>(cache,k,checker);if(k<8){lookups[k]=std::make_unique<Mapped>(geometry+"/q"+std::to_string(k)+".lookup");require(lookups[k]->size==8*atlas.combinations[42][k],"complete original lookup layout");}}}
 Record cached(int k,uint32_t id){auto stamp=Clock::now();uint64_t key=(uint64_t(k)<<32)|id;auto old=low_cache.find(key);if(old!=low_cache.end()){++hits;decode_seconds+=a19char::seconds(stamp);return old->second;}++misses;Record r=levels[k]->get(id);if(k<=5){require(low_cache.size()<44613,"bounded low-dimensional decoded cache");low_cache.emplace(key,r);}decode_seconds+=a19char::seconds(stamp);return r;}
 Lower lower(const std::array<int,9>&ids,int mask){auto stamp=Clock::now();std::vector<std::pair<int,int>>chosen;std::vector<int>original;for(int i=0;i<9;++i)if(mask>>i&1){chosen.emplace_back(ids[i],i);original.push_back(ids[i]);}int k=chosen.size();require(k>=1&&k<=8,"proper original subset");uint32_t type,code;
  if(k<8){auto rank=atlas.rank(original);const auto*p=lookups[k]->p+8ull*rank;type=little(p,4);code=little(p+4,4);}else{std::vector<int>best;std::vector<std::pair<int,int>>mapping;for(int g=0;g<6;++g){auto transformed=chosen;for(auto&v:transformed)v.first=atlas.actions[g][v.first];std::sort(transformed.begin(),transformed.end());std::vector<int>tuple;for(auto v:transformed)tuple.push_back(v.first);if(best.empty()||tuple<best){best=tuple;mapping=transformed;}}chosen=std::move(mapping);uint32_t ordinal=atlas.rank(best);size_t lo=0,hi=10480218;while(lo<hi){size_t mid=(lo+hi)/2;if(little(join.p+12*mid,4)<ordinal)lo=mid+1;else hi=mid;}require(lo<10480218&&little(join.p+12*lo,4)==ordinal,"every original q8 deletion present");type=little(join.p+12*lo+4,4);code=little(join.p+12*lo+8,4);}
  Lower out;unsigned used=0;for(int i=0;i<k;++i){int pos=(code>>(3*i))&7;require(pos<k&&!(used>>pos&1),"complete lower row permutation");used|=1<<pos;out.positions[i]=chosen[pos].second;}require(code>>(3*k)==0,"lower permutation tail");++lookups_done;lookup_seconds+=a19char::seconds(stamp);out.record=cached(k,type);stamp=Clock::now();const Record&r=out.record;for(int i=0;i<k;++i)for(int j=0;j<k;++j)require(r.g[i][j]==atlas.h[ids[out.positions[i]]][ids[out.positions[j]]],"complete original Gram transport");for(int c=0;c<10;++c){long x[8]{};for(int i=0;i<k;++i){long value=atlas.normals[ids[out.positions[i]]][c];for(int j=0;j<i;++j)value-=r.basis[i][j]*x[j];require(r.basis[i][i]>0&&value%r.basis[i][i]==0,"every original column in cached image lattice");x[i]=value/r.basis[i][i];}}require(atlas.subset_index(original)==r.index,"independent full original image index");transport_seconds+=a19char::seconds(stamp);return out;}
 Q base(const std::array<int,9>&ids,int index){std::array<Lower,511>children;for(int mask=1;mask<511;++mask)children[mask]=lower(ids,mask);auto stamp=Clock::now();std::array<Q,512>K{};K[0]=1;
  for(int mask=1;mask<512;++mask){int complement=511^mask;if(!complement){for(int i=0;i<9;++i)K[mask]+=K[mask^(1<<i)];continue;}const Lower&child=children[complement];const Record&r=child.record;std::array<long,8>solved{};if(checker)solved=checker_solve(r);else for(int j=0;j<r.k;++j)solved[j]=r.u[j];Q numerator_sum=0;for(int i=0;i<9;++i)if(mask>>i&1){long numerator=r.det;for(int j=0;j<r.k;++j)numerator-=atlas.h[ids[i]][ids[child.positions[j]]]*solved[j];if(checker)K[mask]+=rational(numerator,r.det)*K[mask^(1<<i)];else numerator_sum+=numerator*K[mask^(1<<i)];}if(!checker)K[mask]=numerator_sum/r.det;}
  Q total=0;for(int mask=0;mask<511;++mask){int size=__builtin_popcount(unsigned(511^mask));Q term;if(checker){Q alpha=mask?children[mask].record.value:Q(1);int child_index=mask?children[mask].record.index:1;term=alpha*child_index*K[511^mask]/index/a19char::factorial(size);}else{Q weight=mask?children[mask].record.value:rational(1,362880);term=weight*K[511^mask];}total+=size%2?-term:term;}total/=checker?-2:-2*index;base_seconds+=a19char::seconds(stamp);return total;}
 Q alpha(const std::array<int,9>&ids,int expected_index,bool expected_ones){auto normals=atlas.literal(ids);auto im=a19char::image(normals);require(im.index==expected_index&&im.ones==expected_ones,"full original parent image index and ones class");Q result=base(ids,im.index);if(!im.ones){auto stamp=Clock::now();result+=a19char::correction(normals,im,checker,correction_stats);correction_seconds+=a19char::seconds(stamp);}return result;}
};
